INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-world:-dr-wilys-revenge-gbc', 'GAMEBOYCOLOR', 'Mega Man World: Dr. Wily''s Revenge GBC', '1999', 'Action / Platform', 'Capcom', '1', 'Classic action platformer', 'Side-scrolling action platformer with boss weapon stealing.', 'Defeat Dr. Wily''s robot masters and stop his latest scheme.', 'Enhanced color port of the GB classic.', 'Mega Man World: Dr. Wily''s Revenge GBC brings the legendary NES-style action to the handheld in full color. Master iconic stages and steal boss powers to defeat the evil scientist.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-xtreme-2---refill-weapon-after-death', 'GAMEBOYCOLOR', 'Mega Man Xtreme 2 - Refill Weapon after Death', '2001', 'ROM Hack', 'Community', '1', 'Gameplay modification', 'Side-scrolling action platformer with boss weapon stealing.', 'Defeat Reploid Mavericks while keeping energy levels full.', 'Action platformer with weapon QoL.', 'This version of Mega Man Xtreme 2 features a "Refill Weapon after Death" enhancement, streamlining the challenging GBC gameplay by ensuring your arsenal is always ready for a rematch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-xtreme-2---shared-health-upgrades', 'GAMEBOYCOLOR', 'Mega Man Xtreme 2 - Shared Health Upgrades', '2001', 'ROM Hack', 'Community', '1', 'Gameplay modification', 'Side-scrolling action platformer with boss weapon stealing.', 'Defeat Reploid Mavericks while keeping energy levels full.', 'Action platformer with shared health.', 'A modified experience of Mega Man Xtreme 2 where health upgrades are shared between X and Zero, allowing for more balanced gameplay and easier character swapping on GBC.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-xtreme-2---shared-weapon-unlocks', 'GAMEBOYCOLOR', 'Mega Man Xtreme 2 - Shared Weapon Unlocks', '2001', 'ROM Hack', 'Community', '1', 'Gameplay modification', 'Side-scrolling action platformer with boss weapon stealing.', 'Defeat Reploid Mavericks while keeping energy levels full.', 'Action platformer with shared unlocks.', 'Enjoy Mega Man Xtreme 2 with shared weapon unlocks. This QoL version ensures that both X and Zero have access to their full arsenal simultaneously for maximum tactical depth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-xtreme-2---xtreme-mode', 'GAMEBOYCOLOR', 'Mega Man Xtreme 2 - Xtreme Mode', '2001', 'ROM Hack', 'Community', '1', 'Alternate difficulty mode', 'Side-scrolling action platformer with boss weapon stealing.', 'Defeat Reploid Mavericks while keeping energy levels full.', 'Hardcore action platformer mode.', 'Experience the ultimate challenge in Mega Man Xtreme 2: Xtreme Mode. Face tougher enemies and bosses in this definitive high-difficulty version of the GBC classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megaman-xtreme-usa', 'GAMEBOYCOLOR', 'Megaman Xtreme (USA)', '2000', 'Action / Platform', 'Capcom', '1', 'Action platformer', 'Side-scrolling action platformer with wall-jumping and upgrades.', 'Defeat the Mavericks and stop the "Nightmare" virus.', 'High-octane Mega Man X action.', 'Megaman Xtreme brings the SNES experience to GBC. Master wall-kicking, dash jumps, and boss weapons in this condensed but intense portable action title.');
