INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pokemon-coral-version-2022-demo-v12', 'GAMEBOYCOLOR', 'Pokemon Coral Version (2022 DEMO v1.2)', '2022', 'RPG', 'Fan-made', '1', 'Monster collecting RPG (ROM hack)', 'Open-world creature RPG in the new Onwa region.', 'Collect 8 badges and explore a brand new world.', 'Modern Pokémon fan-game demo.', 'Pokémon Coral Version is a high-quality GBC fan project. Explore the Onwa region with modern mechanics, a non-linear story, and beautiful custom graphics.');
